import { expect, test, uniqueName } from "../../fixtures";

test.describe("manage vendors", () => {
  test("Update a draft vendor", { tag: "@VEN-08" }, async ({ apiAs }) => {
    // Arrange: a member creates a vendor, which starts in draft.
    const member = await apiAs("member");
    const createResponse = await member.post("/api/vendors", {
      data: {
        name: uniqueName("VEN-08 Draft Vendor"),
        category: "logistics",
        contact_email: "ops@draftvendor.example",
      },
    });
    expect(createResponse.status()).toBe(201);
    const created = await createResponse.json();
    expect(created.status).toBe("draft");

    // Act: change the contact email.
    const newEmail = "billing@acmefreight.example";
    const updateResponse = await member.patch(`/api/vendors/${created.id}`, {
      data: { contact_email: newEmail },
    });

    // Assert: response status and updated field.
    expect(updateResponse.status()).toBe(200);
    const updated = await updateResponse.json();
    expect(updated.id).toBe(created.id);
    expect(updated.contact_email).toBe(newEmail);

    // Assert: audit event recorded for the vendor.
    const auditResponse = await member.get(`/api/vendors/${created.id}/audit`);
    expect(auditResponse.status()).toBe(200);
    const audit = await auditResponse.json();
    const actions = (audit.items as { action: string }[]).map((event) => event.action);
    expect(actions).toContain("vendor.updated");
  });
});
